INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('7fc59114-7232-58c6-8eca-1e937241eff7','arena-b1-reading-a85185c1-99b','B1','reading','reading',2,'What happened after the change?','A town replaced several parking spaces with trees. Some shopkeepers worried about losing customers, but pedestrian visits increased the following summer.','[{"id": "d6106c4c-adfd-5b8a-acec-dbac67623971", "text": "Every shop closed."}, {"id": "d0a377c9-8a42-5c85-9132-ab7e205a42ea", "text": "More people visited on foot."}, {"id": "446653de-9383-58f6-b734-105691d6d42a", "text": "Parking became free."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '7fc59114-7232-58c6-8eca-1e937241eff7','"d0a377c9-8a42-5c85-9132-ab7e205a42ea"'::jsonb,'Pedestrian visits increased cho biết số lượt khách đi bộ tăng lên.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='7fc59114-7232-58c6-8eca-1e937241eff7');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('e268d4a6-dc30-555e-adc2-815a899d36d7','arena-b1-reading-17cf9b5d-6b6','B1','reading','reading',2,'Why did Mina choose the direct flight?','Mina booked a direct flight because she had little time. A cheaper flight required a six-hour connection, which she decided to avoid.','[{"id": "4c8b3cd7-13b7-5626-863a-b1bd30b62a5d", "text": "To save time."}, {"id": "3d6d88bb-d4b0-5509-b676-5ae252459b5f", "text": "To spend less money."}, {"id": "d7840d33-66fe-5d0b-a6a5-11fe14e32869", "text": "To visit another airport."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT 'e268d4a6-dc30-555e-adc2-815a899d36d7','"4c8b3cd7-13b7-5626-863a-b1bd30b62a5d"'::jsonb,'Mina ưu tiên thời gian và tránh chờ nối chuyến dài.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='e268d4a6-dc30-555e-adc2-815a899d36d7');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('311c9a67-e5ad-570c-ab8f-b8ca37a6c858','arena-b1-reading-dd377f75-f54','B1','reading','reading',2,'What did the anonymous system encourage?','The manager invited staff to suggest improvements anonymously. Several useful ideas came from employees who rarely spoke during meetings.','[{"id": "8ec4a909-969e-5c05-ad2a-3089bf3a730c", "text": "Contributions from quieter staff."}, {"id": "9daf30ed-d801-5303-9893-bc4ffb3d107d", "text": "Fewer suggestions."}, {"id": "14b13624-ec40-5bed-bc82-b83f83d5329c", "text": "Longer meetings only."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '311c9a67-e5ad-570c-ab8f-b8ca37a6c858','"8ec4a909-969e-5c05-ad2a-3089bf3a730c"'::jsonb,'Ẩn danh giúp những nhân viên ít phát biểu đóng góp ý kiến.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='311c9a67-e5ad-570c-ab8f-b8ca37a6c858');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('6d600e4b-ebb4-51ca-a403-5f6d8a8cdc23','arena-b1-reading-821412ea-772','B1','reading','reading',2,'Why did Nora borrow the bicycle?','Nora borrowed a bicycle for a week before deciding whether to buy one. She wanted to see if cycling suited her daily routine.','[{"id": "89ef9ae3-bdc8-5eb1-9477-8f8c85eddd36", "text": "To sell it immediately."}, {"id": "9b7f7bbd-31b1-5a70-9c50-f49f1dcd3e23", "text": "To try cycling before buying."}, {"id": "0054e5af-58d1-5c1f-b981-59816262c5bb", "text": "To repair it for a friend."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '6d600e4b-ebb4-51ca-a403-5f6d8a8cdc23','"9b7f7bbd-31b1-5a70-9c50-f49f1dcd3e23"'::jsonb,'Nora muốn thử mức độ phù hợp với sinh hoạt trước khi mua.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='6d600e4b-ebb4-51ca-a403-5f6d8a8cdc23');
