INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('4df8199f-5e33-5044-bf73-b1bfa5f2514e','arena-b2-reading-76ce738d-adc','B2','reading','reading',3,'Why should the results be interpreted cautiously?','A company introduced a four-day week without reducing salaries. Output remained stable, but managers noted that quieter seasonal demand may have influenced the results.','[{"id": "ffd94bf9-20ee-5b5a-8ddd-782d3b19350b", "text": "Salaries were reduced."}, {"id": "a867475a-9ed7-5662-baf4-fdee2a16bb29", "text": "Output was never measured."}, {"id": "bdc29352-f1a8-5eff-b538-e9429266e9bb", "text": "Seasonal demand may have affected them."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
