INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('a506211e-85bc-53b3-8e81-7bba77249eed','arena-b2-reading-de698ec0-88c','B2','reading','reading',3,'What approach does the guide support?','A travel guide recommends visiting popular sites early and using locally owned businesses. It argues that small choices can reduce pressure on residents without preventing tourism.','[{"id": "341e4dc3-21b4-5cdd-bf49-936a8b091b82", "text": "Adjusting tourist behaviour to reduce harm."}, {"id": "bd0a5c00-64ce-57b6-925f-2a0e767cb5b1", "text": "Replacing local shops with chains."}, {"id": "2d5c108b-2aea-5b10-8d96-c6df72b48e30", "text": "Banning all visitors."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
