INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '0827ff69-b8a5-5dbe-8bf2-3d811cff314b','"3bbb11a7-6d4d-517f-b13c-aaecb1934433"'::jsonb,'Mẫu tự nguyện và thiên về nhân viên văn phòng có thể không đại diện mọi lao động.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='0827ff69-b8a5-5dbe-8bf2-3d811cff314b');
