INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '3f64466d-abbc-53ec-88c9-f32ecef1d8b9','"6048458c-2403-5582-a63c-bc9f01bdf4fd"'::jsonb,'Bỏ phí có thể giúp người mượn bớt ngại trả sách do sợ tiền phạt.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='3f64466d-abbc-53ec-88c9-f32ecef1d8b9');
