INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '548d67f5-bd63-5299-9513-b3289bde8b98','"3c3f8c6e-f781-59d4-9038-fdd2b8bbf948"'::jsonb,'Không biết hành khách trước đó đi bộ hay lái xe nên chưa xác định được số chuyến ô tô có giảm hay không.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='548d67f5-bd63-5299-9513-b3289bde8b98');
