INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '46a9854c-7660-5271-b5df-c21551d60d5b','["c4994962-9e78-5c7a-9353-359c7b340e0c", "e7252e12-9f76-5d62-9da6-bb2273a3b31b", "e702376e-d18b-5c22-b5a0-bac5bc3b6b57", "4692bbbc-3b8f-5d9b-894d-8795b68caa68", "3f71f1b5-0e16-51c2-ae0e-2e7647824b46", "62958ceb-b02d-5887-bd4a-18859791eedd", "e3a38fc0-93fc-5157-8797-c25e67d6877f", "98090b95-e75b-5ddf-8a6c-1b1654c4ef16", "26517682-24a9-561b-b80c-6bc8e510fb40", "3d5a1839-1dbe-5969-b57b-ede91390458d"]'::jsonb,'Trật tự đúng: The proposal is defensible insofar as its underlying premises hold. Insofar as giới hạn tính có thể bảo vệ của đề xuất theo điều kiện các tiền đề còn đúng.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='46a9854c-7660-5271-b5df-c21551d60d5b');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('17baca62-10c8-5fba-92e7-c8a61564fa99','arena-c1-sentence_order-5a603d87-326','C1','sentence_structure','sentence_order',3,'Put every token in order to make one sentence.',NULL,'[{"id": "dad3f8fe-20a9-55b1-b1c8-df7c784c6992", "text": "assumption"}, {"id": "512e1a4c-4d15-5165-98d8-4d12703fce77", "text": "So"}, {"id": "7d20fab6-8cde-5dfd-a5ca-d04acba5bf19", "text": "was"}, {"id": "73e5cc4f-6b8a-5ae6-bf06-9d0dfab908e3", "text": "thought"}, {"id": "5273b2e8-ff52-5ef0-9c45-e71188f58df0", "text": "to"}, {"id": "ea4bb34a-900f-5c9c-80f0-316c36750e99", "text": "question"}, {"id": "2abed58c-8db6-5644-83dd-3a60842d9312", "text": "it."}, {"id": "8b340d48-6996-5fb0-afcc-e8ba5d12f57e", "text": "pervasive"}, {"id": "c86e548e-6f18-5848-9c64-0ce98a39c68e", "text": "the"}, {"id": "7072b8d7-4150-5ee6-ac6f-29ee7b2244d6", "text": "few"}, {"id": "e141ace0-b24a-551e-aca4-5396cc01b51c", "text": "that"}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '17baca62-10c8-5fba-92e7-c8a61564fa99','["512e1a4c-4d15-5165-98d8-4d12703fce77", "8b340d48-6996-5fb0-afcc-e8ba5d12f57e", "7d20fab6-8cde-5dfd-a5ca-d04acba5bf19", "c86e548e-6f18-5848-9c64-0ce98a39c68e", "dad3f8fe-20a9-55b1-b1c8-df7c784c6992", "e141ace0-b24a-551e-aca4-5396cc01b51c", "7072b8d7-4150-5ee6-ac6f-29ee7b2244d6", "73e5cc4f-6b8a-5ae6-bf06-9d0dfab908e3", "5273b2e8-ff52-5ef0-9c45-e71188f58df0", "ea4bb34a-900f-5c9c-80f0-316c36750e99", "2abed58c-8db6-5644-83dd-3a60842d9312"]'::jsonb,'Trật tự đúng: So pervasive was the assumption that few thought to question it. So pervasive đứng đầu dẫn tới đảo was trước the assumption; that mở mệnh đề kết quả.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='17baca62-10c8-5fba-92e7-c8a61564fa99');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('0d7c010e-778f-5a06-859c-9b471b01330f','arena-c1-reading-3471164c-0dc','C1','reading','reading',3,'Why do the authors qualify their conclusion?','An evaluation linked urban tree cover to improved wellbeing. Yet wealthier districts also had better healthcare and lower traffic density. The authors therefore characterised their findings as suggestive rather than conclusive.','[{"id": "aefb879b-08fd-5788-a71a-ad3554e4ccbe", "text": "Other district characteristics may explain the association."}, {"id": "197fe8d4-b8d1-5762-a598-067b930d770d", "text": "They rejected all observational research."}, {"id": "1492e3b3-6e41-5124-a76c-001466badf14", "text": "Tree cover was identical everywhere."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '0d7c010e-778f-5a06-859c-9b471b01330f','"aefb879b-08fd-5788-a71a-ad3554e4ccbe"'::jsonb,'Các đặc điểm cùng biến thiên có thể giải thích tương quan, nên chưa thể kết luận nhân quả.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='0d7c010e-778f-5a06-859c-9b471b01330f');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('614da371-f4c2-5bac-ad25-60c84d7efe24','arena-c1-reading-9836feef-25f','C1','reading','reading',3,'What does the omission undermine?','A firm advertises an efficiency gain after automating routine tasks. Its report omits the additional review work shifted to external contractors, making comparisons with the previous system difficult.','[{"id": "d2f5e8dd-56d0-5756-aa09-52b9a3df9b6b", "text": "The existence of any automation."}, {"id": "c51243cc-1437-55e1-a2d3-3914347491cf", "text": "The comparability of the claimed efficiency gain."}, {"id": "f17d67b4-0c70-5f3d-9401-4b0a54a5e1a3", "text": "The contractors’ legal right to work."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '614da371-f4c2-5bac-ad25-60c84d7efe24','"c51243cc-1437-55e1-a2d3-3914347491cf"'::jsonb,'Bỏ qua công việc chuyển sang bên ngoài làm phép so sánh hiệu quả thiếu nhất quán về phạm vi.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='614da371-f4c2-5bac-ad25-60c84d7efe24');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('0b1c7ceb-1303-5607-a12e-9c8f092e8f64','arena-c1-reading-bc6f4826-0d7','C1','reading','reading',3,'What distinction underpins the criticism?','A heritage project restored the appearance of a district while displacing many long-term residents. Critics argue that preserving buildings alone can obscure the loss of the social practices that gave those buildings meaning.','[{"id": "aaabc755-ef93-5f41-9d57-de206feabee4", "text": "Tourism versus every form of conservation."}, {"id": "6dd0149d-68fd-55e8-8b8c-6ee82c3b2196", "text": "Physical preservation versus continuity of community life."}, {"id": "64ce3756-d9a3-5606-905e-62ba9da88709", "text": "Old buildings versus all new technology."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '0b1c7ceb-1303-5607-a12e-9c8f092e8f64','"6dd0149d-68fd-55e8-8b8c-6ee82c3b2196"'::jsonb,'Phê bình phân biệt bảo tồn vật chất với duy trì đời sống và thực hành cộng đồng.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='0b1c7ceb-1303-5607-a12e-9c8f092e8f64');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('fc2e1aef-76e6-5a6a-b66b-6a7853e70118','arena-c1-reading-d6509711-ca0','C1','reading','reading',3,'What is the purpose of disaggregated analysis here?','The review acknowledges that a policy may improve average outcomes while worsening conditions for a minority. It calls for disaggregated analysis before declaring the intervention successful.','[{"id": "60b06290-5bc1-59c5-be42-b74752547dd0", "text": "To remove minority groups from the data."}, {"id": "5cdcd5f6-4cb3-5150-8847-83f5b187dc7f", "text": "To reveal uneven effects hidden by averages."}, {"id": "b5148aac-2741-59b0-b258-9ec692765dc8", "text": "To substitute anecdotes for all measurements."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT 'fc2e1aef-76e6-5a6a-b66b-6a7853e70118','"5cdcd5f6-4cb3-5150-8847-83f5b187dc7f"'::jsonb,'Phân tích theo nhóm làm rõ tác động không đồng đều mà giá trị trung bình có thể che khuất.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='fc2e1aef-76e6-5a6a-b66b-6a7853e70118');
INSERT INTO public.arena_questions(id,slug,cefr_level,topic,kind,difficulty,prompt,passage,options,left_items,right_items) VALUES('301ad941-d190-552c-b501-c9d55b723539','arena-c1-reading-c4b5e537-268','C1','reading','reading',3,'Which inference follows from the distinction?','The analyst distinguishes uncertainty due to incomplete data from uncertainty arising from an inherently unpredictable process. Collecting more observations may reduce the former without eliminating the latter.','[{"id": "017eb201-6d60-57dc-a58f-670e7727b679", "text": "All uncertainty disappears with enough observations."}, {"id": "7c361e3e-2677-50e3-9dcf-2a69659b4406", "text": "More data need not remove every source of uncertainty."}, {"id": "289582b6-a93f-50b0-9669-cfba9025aab9", "text": "Incomplete data make every process inherently unpredictable."}]'::jsonb,'[]'::jsonb,'[]'::jsonb) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.arena_answer_keys(question_id,answer,explanation_vi) SELECT '301ad941-d190-552c-b501-c9d55b723539','"7c361e3e-2677-50e3-9dcf-2a69659b4406"'::jsonb,'Đoạn văn phân biệt thiếu dữ liệu và bất định vốn có; thêm quan sát chỉ có thể giảm loại thứ nhất.' WHERE NOT EXISTS(SELECT 1 FROM public.arena_answer_keys WHERE question_id='301ad941-d190-552c-b501-c9d55b723539');
